def I(name, size=None, cls=""):
    s = f' pl-ico--{size}' if size in (20, 24) else ""
    extra = f" {cls}" if cls else ""
    return f'<svg class="pl-ico{s}{extra}" viewBox="0 0 24 24" aria-hidden="true">{P[name]}</svg>'
